simple SyncNode
{
	parameters:
		int NumberOfHLANodes = default(5);
		double SynchTime = default(0.000011);
		double StartSynchTime = default(0);

		bool sendInitialMessage = default(false);
		@display("i=block/routing");
	gates:
		input in;
		output out;
}
